/* The long-form body of thirteen programme pages, keyed by route.
 *
 * These thirteen came across from standalone builds of one template — problem
 * solving, financial literacy, confidence, leadership, drawing, singing,
 * swimming, dance, indoor games, drama, music, outdoor games, yoga. They differ
 * only in what they say, so they render through one component
 * (pages/ProgrammePage.jsx) and keep their words here.
 *
 * What is NOT in this file, on purpose:
 *
 *   - The route, the SEO record, the hero chips, the quick answer and the
 *     stage-by-stage curriculum. Those already live in data/catalog/programmes.js
 *     and are read by the menu, the sitemap and lib/seo.js. Duplicating them
 *     here would give every page two sources of truth.
 *   - Contact details and the address, which come from data/site.js.
 *   - The programme name in the booking form, which the page resolves through
 *     lib/course.js — the same lookup the trial modal uses.
 *
 * Every section is optional. A page that has no vocabulary block, or no
 * interactive, simply leaves the key out.
 *
 * The claims kept verbatim from the sources are the ones that say what these
 * classes are NOT: no guaranteed marks, no fixed timeline, no treatment for
 * shyness or a developmental condition, no promise a quiet child becomes an
 * outgoing one. Those are the most useful sentences on the page and the first
 * ones a competitor would drop.
 */

